begin;

alter table public.together_locations
  add column if not exists canonical_lore jsonb not null default '{}'::jsonb;

alter table public.together_locations drop constraint if exists together_locations_canonical_lore_object;
alter table public.together_locations add constraint together_locations_canonical_lore_object
  check(jsonb_typeof(canonical_lore)='object');

create index if not exists together_locations_canonical_lore_gin
  on public.together_locations using gin(canonical_lore);

with lore(slug, canonical_lore) as (values
  ('juniper-cafe','{"summary":"A neighborhood cafe where regulars linger and conversations carry more weight than the quick service suggests.","atmosphere":["warm","unhurried","creative neighborhood regulars"],"sensoryDetails":["cardamom and espresso near the counter","ceramic cups clicking behind the bar","soft street noise through the front windows"],"signatureDetails":["cardamom latte","small open-mic stage","corner table beneath the community board"],"layout":["long front windows","counter along the left wall","small tables toward the back","low stage near the rear"],"crowdRhythm":{"morning":"Commuters move quickly while regulars claim the window seats.","afternoon":"Laptop work and quiet meetings fill most tables.","evening":"The room slows down; open-mic nights draw a closer crowd.","late_night":"Staff stack chairs around the last lingering conversations."},"conversationHooks":["the rotating flyers on the community board","whether tonight''s open mic will be any good","the owner always remembers regular orders"],"stableFacts":["The cafe serves food into the evening.","Open-mic performances use the small rear stage."],"localEtiquette":["Regulars do not rush people out of the corner tables."],"nearbyLocationSlugs":["alder-district","paper-trail","glassline-gallery","riverwalk"]}'::jsonb),
  ('maya-apartment','{"summary":"A private, lived-in apartment shaped by photography work, plants, and half-finished playlists.","atmosphere":["private","creative","slightly cluttered but intentional"],"sensoryDetails":["paper and photo chemicals near the worktable","plants crowding the brightest windows","music usually playing quietly"],"signatureDetails":["contact sheets clipped above the desk","camera gear beside the entry","a shelf of mismatched records"],"layout":["open living room and kitchen","photo-editing desk by the window","small balcony","private bedroom beyond the hall"],"crowdRhythm":{"morning":"Quiet except for coffee and a hurried search for equipment.","evening":"Warm lamps and music make the living room feel sheltered from the city.","late_night":"The editing desk is often the only light still on."},"conversationHooks":["the newest contact sheet on the wall","which plant is barely surviving","the playlist that was never finished"],"stableFacts":["This is a private residence, not a public venue.","Visits require an invitation or established shared scene."],"localEtiquette":["Do not imply the user is inside unless canonical scene state establishes co-presence."],"nearbyLocationSlugs":["juniper-cafe","common-market","riverwalk"]}'::jsonb),
  ('skyline-rooftop','{"summary":"A rooftop gathering space where films, trivia, and the city skyline compete for attention.","atmosphere":["open-air","cinematic","casually romantic after dark"],"sensoryDetails":["wind above the surrounding buildings","projector hum during movie nights","city traffic softened by the height"],"signatureDetails":["portable outdoor screen","strings of warm bulbs","blankets stored near the stairwell"],"layout":["screen wall at one end","clusters of low seats","open skyline edge behind a safe glass rail"],"crowdRhythm":{"afternoon":"Mostly empty and bright.","evening":"Small groups arrive before screenings and trivia.","late_night":"The crowd thins and the skyline becomes the main attraction."},"conversationHooks":["whether the skyline is better than the movie","who brought the worst snacks","the safest place to sit when the wind picks up"],"stableFacts":["Most programming happens after sunset.","Weather can change rooftop plans."],"localEtiquette":["People keep voices down once a screening begins."],"nearbyLocationSlugs":["marquee-cinema","northside-bar","riverwalk"]}'::jsonb),
  ('northside-bar','{"summary":"A relaxed neighborhood bar built around live music, trivia, and regulars who take both more seriously than they admit.","atmosphere":["friendly","competitive","loud without feeling like a nightclub"],"sensoryDetails":["fried food from the kitchen","chalk dust near the trivia board","amplifiers warming up before sets"],"signatureDetails":["weekly trivia","small live-music stage","surprisingly good fries"],"layout":["long bar facing the room","booths along the wall","compact stage near the back"],"crowdRhythm":{"afternoon":"Quiet setup and a few early regulars.","evening":"Trivia teams and after-work groups take over the booths.","late_night":"Music replaces trivia and the room gets louder."},"conversationHooks":["the overly serious trivia teams","which local band is playing","why the fries are better than expected"],"stableFacts":["The venue is 21+.","Trivia and live music are recurring draws."],"localEtiquette":["Do not claim a trivia result unless a canonical event records it."],"nearbyLocationSlugs":["static-house","lucky-note","lantern-dive"]}'::jsonb),
  ('riverwalk','{"summary":"A tree-lined path beside the water that feels most intimate when the city lights begin reflecting at dusk.","atmosphere":["open","calm","good for unhurried conversation"],"sensoryDetails":["water against the retaining wall","bikes passing on the wider stretches","cooler air near the river after sunset"],"signatureDetails":["dusk reflections","small overlooks","benches beneath mature trees"],"layout":["long riverside path","occasional steps down toward the water","several overlook pockets"],"crowdRhythm":{"morning":"Runners and dog walkers use the path.","afternoon":"The sunny stretches stay busier than the shaded benches.","evening":"Walkers slow down for the lights on the water.","late_night":"The path is sparse and quiet."},"conversationHooks":["which skyline reflection makes the best photograph","the boats passing farther downstream","whether to keep walking or take a bench"],"stableFacts":["It is a public outdoor path.","Dusk is the most visually distinctive time."],"localEtiquette":["Keep to one side when bikes pass."],"nearbyLocationSlugs":["juniper-cafe","halcyon-park","skyline-rooftop"]}'::jsonb),
  ('photography-studio','{"summary":"A working daylight studio where polished shoots coexist with cables, edits, and difficult client notes.","atmosphere":["professional","creative","busy during shoots"],"sensoryDetails":["warm equipment fans","paper backdrops shifting underfoot","coffee beside the editing station"],"signatureDetails":["large north-facing windows","rolling backdrop system","contact-sheet review wall"],"layout":["main shooting bay","equipment cage","editing desk","small client seating area"],"crowdRhythm":{"morning":"Equipment checks and setup dominate the room.","afternoon":"Client work and active shoots make interruptions difficult.","evening":"Editing and cleanup replace the larger crew."},"conversationHooks":["the impossible client revision","which lens is currently on the camera","the best image from the latest shoot"],"stableFacts":["This is a workplace.","Active shoots should be treated as busy or limited presence."],"localEtiquette":["Do not move equipment or interrupt an active take."],"nearbyLocationSlugs":["glassline-gallery","juniper-cafe","common-market"]}'::jsonb),
  ('ember-and-rye','{"summary":"A bright brunch room where paper menus, good coffee, and a slow-moving line make mornings stretch out.","atmosphere":["sunlit","social","casual"],"sensoryDetails":["toasted rye and butter","coffee grinder near the counter","morning light across pale wood tables"],"signatureDetails":["seasonal toast board","house jam","paper menus clipped to boards"],"layout":["order counter near the entrance","shared center table","smaller window tables"],"crowdRhythm":{"morning":"The line is longest and the room is energetic.","afternoon":"Late brunch settles into lingering coffee.","evening":"Closed."},"conversationHooks":["whether the line is worth it","the changing jam flavor","people watching from the front windows"],"stableFacts":["It closes in the afternoon.","Ordering happens at the counter."],"nearbyLocationSlugs":["common-market","moss-and-crumb","halcyon-park"]}'::jsonb),
  ('sora-table','{"summary":"A small candlelit restaurant designed to make an ordinary dinner feel deliberate.","atmosphere":["intimate","quiet","occasion-worthy"],"sensoryDetails":["candle wax and warm bread","low conversation across closely spaced tables","soft light reflected in dark glass"],"signatureDetails":["compact seasonal menu","corner two-top","small celebration desserts"],"layout":["narrow dining room","bar-height seats near the kitchen","few secluded two-person tables"],"crowdRhythm":{"evening":"Reservations arrive in waves; later seatings are quieter.","late_night":"The final tables linger over wine and dessert."},"conversationHooks":["the shortest menu item with the strangest description","whether the corner table is actually private","what counts as an occasion"],"stableFacts":["Dinner service begins in the evening.","The room is intentionally small."],"localEtiquette":["It is a conversation-focused room rather than a loud group venue."],"nearbyLocationSlugs":["velvet-hour","glassline-gallery","riverwalk"]}'::jsonb),
  ('taqueria-lumen','{"summary":"A bright, fast-moving taco spot whose cheerful spice warnings are not always trustworthy.","atmosphere":["casual","bright","energetic"],"sensoryDetails":["griddled tortillas","citrus and hot sauce","music over a busy open counter"],"signatureDetails":["unreliable spice scale","late lunch crowd","colorful counter tiles"],"layout":["open ordering counter","small two-person tables","pickup shelf by the door"],"crowdRhythm":{"afternoon":"Lunch traffic keeps the counter moving.","evening":"Takeout orders and casual dinners fill the small room.","late_night":"The crowd thins but the hot sauce challenges continue."},"conversationHooks":["whether the spice label can be trusted","which salsa is actually hottest","the fastest route to a free table"],"stableFacts":["The restaurant is casual and counter-service.","The spice scale is part of its reputation."],"nearbyLocationSlugs":["pixel-and-pint","lantern-dive","common-market"]}'::jsonb),
  ('velvet-hour','{"summary":"An intimate cocktail lounge where amber light, deep booths, and a black upright piano keep the room low-key.","atmosphere":["intimate","polished","quietly romantic"],"sensoryDetails":["citrus oils and walnut","low piano notes on Thursdays","amber reflections across brass and dark glass"],"signatureDetails":["black upright piano","deep walnut booths","bartender recommendations based on mood rather than a long menu"],"layout":["amber bar along the rear wall","deep booths at the quieter side","piano with a few close tables"],"crowdRhythm":{"afternoon":"Closed.","evening":"Conversation-focused tables fill gradually after work.","late_night":"The piano side becomes the center of the room without turning into a dance floor."},"conversationHooks":["what the pianist will play next","whether to trust the bartender''s off-menu suggestion","which booth feels most private"],"stableFacts":["The pianist plays on Thursdays.","There are no sports televisions or large dance floor."],"localEtiquette":["Keep conversation below the music near the piano."],"nearbyLocationSlugs":["paper-trail","glassline-gallery","sora-table","alder-district"]}'::jsonb),
  ('lantern-dive','{"summary":"A friendly neighborhood dive where inexpensive drinks, pool, and excellent fries matter more than polish.","atmosphere":["unpretentious","social","regular-driven"],"sensoryDetails":["fryer heat near the kitchen pass","pool balls from the back corner","old wood and neon near the bar"],"signatureDetails":["better-than-expected fries","worn pool table","regulars who know the staff"],"layout":["long front bar","pool table at the back","high-top tables along one wall"],"crowdRhythm":{"afternoon":"A handful of regulars keep it quiet.","evening":"After-work groups and pool games make it busier.","late_night":"The room is lively but still recognizable as a neighborhood bar."},"conversationHooks":["who gets the next pool game","why the fries are the best item","the history behind a faded sign"],"stableFacts":["It is casual rather than upscale.","Pool and fries are reliable fixtures."],"nearbyLocationSlugs":["northside-bar","lucky-note","taqueria-lumen"]}'::jsonb),
  ('moss-and-crumb','{"summary":"A tiny plant-filled bakery built around warm bread, precise pastries, and a limited number of morning seats.","atmosphere":["quiet","cozy","best early"],"sensoryDetails":["warm bread and butter","condensation on the plant-filled windows","paper pastry bags rustling near the counter"],"signatureDetails":["daily bread board","small pastry case","window seats that disappear before noon"],"layout":["narrow counter","three small window tables","bread shelves behind the register"],"crowdRhythm":{"morning":"Seats fill quickly with neighborhood regulars.","afternoon":"Mostly takeaway; seating is usually unavailable.","evening":"Closed."},"conversationHooks":["which pastry will sell out first","the handwritten bread board","whether to take breakfast to the park"],"stableFacts":["The bakery closes at 4 PM.","Seating is not reliably available after noon."],"localEtiquette":["Do not hold a table before ordering."],"nearbyLocationSlugs":["ember-and-rye","paper-trail","halcyon-park"]}'::jsonb),
  ('marquee-cinema','{"summary":"A restored neighborhood theater whose late screenings and old architectural details make movie night feel specific.","atmosphere":["nostalgic","cinematic","lively before showtime"],"sensoryDetails":["buttered popcorn in the lobby","red carpet underfoot","muffled trailers through auditorium doors"],"signatureDetails":["restored marquee","excellent late showing","single large auditorium with a small balcony"],"layout":["ticket lobby beneath the marquee","central concession stand","main auditorium","small upper balcony"],"crowdRhythm":{"afternoon":"Matinees draw a sparse mixed crowd.","evening":"The lobby fills quickly before major showings.","late_night":"The final audience is smaller and more devoted."},"conversationHooks":["whether the balcony seats are worth the stairs","the most misleading poster in the lobby","which snack combination is indefensible"],"stableFacts":["The theater is restored rather than a modern multiplex.","Late showings are part of its reputation."],"localEtiquette":["Conversation stops once the film starts."],"nearbyLocationSlugs":["pixel-and-pint","side-street-comedy","skyline-rooftop"]}'::jsonb),
  ('static-house','{"summary":"An intimate live-music room where being close to the stage matters more than comfort.","atmosphere":["loud","immediate","creative"],"sensoryDetails":["amplifier warmth","bass through the floor","cold air each time the back door opens"],"signatureDetails":["low stage","rotating local lineup","hand-stamped entry"],"layout":["standing floor in front of the stage","small side bar","narrow back corridor"],"crowdRhythm":{"afternoon":"Closed while crews load in.","evening":"The room builds from soundcheck to a close crowd.","late_night":"The last set ends into a noisy sidewalk exit."},"conversationHooks":["which band surprised the room","where to stand without blocking the sound booth","whether showing up without a plan was a good idea"],"stableFacts":["It is a small live-music room, not an arena.","Most events are standing-room."],"localEtiquette":["Do not talk through a quiet set near the stage."],"nearbyLocationSlugs":["northside-bar","needles-and-notes","lucky-note"]}'::jsonb),
  ('lucky-note','{"summary":"A karaoke bar where private nerves become public confidence after the room warms up.","atmosphere":["playful","high-energy","supportive when the crowd is good"],"sensoryDetails":["microphone reverb","song intros cutting through conversation","ice and glassware near the bar"],"signatureDetails":["large shared song queue","small stage","crowd that gets braver after 10 PM"],"layout":["central stage and screen","bar along one side","booths facing the performance area"],"crowdRhythm":{"evening":"Early singers test the room while groups choose songs.","late_night":"The queue grows and the whole room sings along more often."},"conversationHooks":["who should choose the next song","the most ambitious name in the queue","whether a duet is safer or more dangerous"],"stableFacts":["Performances use a public stage.","The venue becomes busiest after 10 PM."],"localEtiquette":["The crowd supports sincere attempts more than perfect singing."],"nearbyLocationSlugs":["static-house","northside-bar","lantern-dive"]}'::jsonb),
  ('side-street-comedy','{"summary":"A brick-basement comedy club where the front row is both the best seat and the riskiest choice.","atmosphere":["close","unpredictable","laughter-driven"],"sensoryDetails":["brick walls holding the room''s noise","small table candles","drinks moving carefully between tight rows"],"signatureDetails":["rotating local lineup","dangerous front row","low stage beneath exposed pipes"],"layout":["stairs down from street level","compact stage","tight rows of small tables"],"crowdRhythm":{"evening":"The room fills just before the first set.","late_night":"Later sets are looser and more unpredictable."},"conversationHooks":["whether to risk the front row","which joke divided the room","the difference between the early and late lineup"],"stableFacts":["It is a basement venue.","The lineup rotates rather than centering one permanent act."],"localEtiquette":["Do not interrupt performers unless they directly engage the table."],"nearbyLocationSlugs":["marquee-cinema","pixel-and-pint","lantern-dive"]}'::jsonb),
  ('pixel-and-pint','{"summary":"A cozy barcade where friendly competition quickly becomes evidence for future teasing.","atmosphere":["playful","competitive","busy"],"sensoryDetails":["arcade chimes layered over conversation","joysticks clicking","bright cabinet light against darker bar seating"],"signatureDetails":["classic cabinet row","two-player fighting games","scoreboard near the bar"],"layout":["arcade cabinets around the perimeter","bar through the center","small tables between game clusters"],"crowdRhythm":{"afternoon":"Open games and a relaxed after-work start.","evening":"Pairs and groups compete for popular cabinets.","late_night":"The bar gets louder while the game floor stays active."},"conversationHooks":["which game settles the argument","whether the high score is legitimate","who is pretending not to care about losing"],"stableFacts":["The room combines a bar and arcade floor.","Popular two-player cabinets may require waiting."],"localEtiquette":["Place a token or follow the visible queue before taking the next game."],"nearbyLocationSlugs":["marquee-cinema","side-street-comedy","taqueria-lumen"]}'::jsonb),
  ('glassline-gallery','{"summary":"A contemporary gallery whose calm daytime rooms change completely during crowded opening nights.","atmosphere":["minimal","observant","social during openings"],"sensoryDetails":["quiet footsteps on polished floors","white walls catching indirect light","wine glasses and conversation on opening nights"],"signatureDetails":["large central installation room","smaller project gallery","opening-night crowd that spills toward the entrance"],"layout":["front reception","large central gallery","two quieter side rooms","small rear project space"],"crowdRhythm":{"afternoon":"Visitors move slowly through mostly quiet rooms.","evening":"Opening nights become crowded and professionally social.","late_night":"Only special events remain open late."},"conversationHooks":["which work people are avoiding talking about","how the central installation changes the room","who came to see art and who came to network"],"stableFacts":["Normal gallery hours end in the early evening.","Opening nights are significantly busier than ordinary visits."],"localEtiquette":["Do not touch displayed work unless explicitly invited."],"nearbyLocationSlugs":["paper-trail","velvet-hour","photography-studio","alder-district"]}'::jsonb),
  ('paper-trail','{"summary":"A quiet bookshop where handwritten staff notes and a rainy-day corner make browsing feel personal.","atmosphere":["quiet","thoughtful","unhurried"],"sensoryDetails":["paper and old wood","rain tapping the front glass when weather turns","soft page turns near the reading corner"],"signatureDetails":["handwritten staff recommendation cards","rainy-day chair","small coffee counter"],"layout":["new releases near the entrance","narrow themed shelves","reading corner at the back","small coffee counter beside it"],"crowdRhythm":{"morning":"Quiet browsers and coffee regulars.","afternoon":"The aisles become busier but remain subdued.","evening":"A smaller crowd lingers near readings or the back corner."},"conversationHooks":["the most opinionated staff note","which book belongs in the rainy-day chair","whether to choose a gift or something selfish"],"stableFacts":["The shop sells books, coffee, and small gifts.","The back corner is the quietest part of the store."],"localEtiquette":["Keep phone calls outside and return browsed books to the marked cart."],"nearbyLocationSlugs":["velvet-hour","glassline-gallery","moss-and-crumb","alder-district"]}'::jsonb),
  ('needles-and-notes','{"summary":"A record shop where listening recommendations turn into small, enjoyable arguments.","atmosphere":["curated","opinionated","music-focused"],"sensoryDetails":["cardboard sleeves and old wood bins","brief headphone leakage","a full album playing from behind the counter"],"signatureDetails":["staff recommendation wall","listening station","used-bin surprises"],"layout":["new releases along the front","genre bins through the center","used records at the back","listening station beside the counter"],"crowdRhythm":{"morning":"Serious browsers move through a quiet shop.","afternoon":"Recommendations and listening-station waits become common.","evening":"The final crowd tends to know exactly what it wants."},"conversationHooks":["the recommendation most likely to start an argument","what is hiding in the used bin","whether cover art is a valid reason to buy something"],"stableFacts":["The store sells both new and used records.","Customers can sample selected records at the listening station."],"localEtiquette":["Ask before opening sealed records."],"nearbyLocationSlugs":["static-house","juniper-cafe","paper-trail"]}'::jsonb),
  ('meridian-fitness','{"summary":"A bright neighborhood gym that feels practical rather than performative.","atmosphere":["calm","routine-driven","welcoming"],"sensoryDetails":["rubber flooring and clean towels","morning light through tall windows","low equipment noise without nightclub music"],"signatureDetails":["bright front training room","small recovery area","classes without aggressive sales pitches"],"layout":["cardio by the windows","weights toward the rear","studio room","small recovery corner"],"crowdRhythm":{"morning":"Regulars move efficiently before work.","afternoon":"The gym is quieter and easier to navigate.","evening":"Classes and after-work workouts make it busiest."},"conversationHooks":["which class looked easier on the schedule","whether recovery counts as part of the workout","the regular who never changes routines"],"stableFacts":["It opens early and closes at 10 PM.","The atmosphere is neighborhood-focused rather than luxury-oriented."],"localEtiquette":["Wipe down equipment and do not interrupt an active set."],"nearbyLocationSlugs":["common-market","halcyon-park","riverwalk"]}'::jsonb),
  ('common-market','{"summary":"A busy neighborhood market where ordinary errands regularly become longer social detours.","atmosphere":["practical","crowded","locally social"],"sensoryDetails":["flowers near the entrance","produce mist and bakery warmth","cart wheels over uneven floor seams"],"signatureDetails":["front flower stand","compact bakery counter","community notice board by checkout"],"layout":["produce at the entrance","narrow grocery aisles","prepared food and bakery at the rear","checkout line beside flowers"],"crowdRhythm":{"morning":"Quick neighborhood errands keep the aisles moving.","afternoon":"The store is steady and easiest to browse.","evening":"After-work traffic creates the longest checkout lines."},"conversationHooks":["the unnecessary thing that ended up in the basket","whether the flower stand is a trap","who always gets stuck in the slow checkout line"],"stableFacts":["It combines groceries, flowers, and prepared food.","Evening checkout lines are usually longest."],"localEtiquette":["Keep carts clear of the narrow center aisles."],"nearbyLocationSlugs":["ember-and-rye","meridian-fitness","maya-apartment"]}'::jsonb),
  ('alder-district','{"summary":"A walkable creative-commercial district linking galleries, books, cocktails, errands, and neighborhood streets.","atmosphere":["walkable","creative","busy without feeling like downtown"],"sensoryDetails":["storefront music mixing on the sidewalk","tree shade between brick buildings","delivery bikes moving through side streets"],"signatureDetails":["independent storefronts","gallery-and-bookshop stretch","easy transition from afternoon errands to evening plans"],"layout":["main shopping street","quieter side streets","small plaza near the gallery block"],"crowdRhythm":{"morning":"Shops open gradually around commuters and deliveries.","afternoon":"Shopping, coffee, and gallery traffic overlap.","evening":"Restaurants and Velvet Hour keep the district active.","late_night":"Activity concentrates around the lounge and late food."},"conversationHooks":["which storefront changed again","whether to browse before getting drinks","the fastest route from the gallery block"],"stableFacts":["Velvet Hour, Paper Trail, and Glassline Gallery are in Alder District.","The area is designed to be explored on foot."],"localEtiquette":["Sidewalk tables narrow the busiest blocks."],"nearbyLocationSlugs":["velvet-hour","paper-trail","glassline-gallery","juniper-cafe"]}'::jsonb),
  ('halcyon-park','{"summary":"A spacious city park whose long paths, pond, and shaded lawns offer room to slow down.","atmosphere":["open","restorative","quiet away from the main path"],"sensoryDetails":["leaves moving above the paths","water birds near the pond","distant city noise at the park edges"],"signatureDetails":["pond loop","large reading lawn","shaded benches off the main path"],"layout":["main walking loop","pond at the center","open lawn","smaller wooded path"],"crowdRhythm":{"morning":"Runners and dog walkers use the main loop.","afternoon":"Picnics and readers spread across the lawn.","evening":"The pond path becomes quieter and cooler."},"conversationHooks":["which path avoids the busiest lawn","the bird that keeps returning to the pond edge","whether to walk or stay on the grass"],"stableFacts":["It is a public park with a pond and multiple paths.","The wooded path is quieter than the central lawn."],"localEtiquette":["Keep picnic areas clear of the main walking loop."],"nearbyLocationSlugs":["moss-and-crumb","lark-botanical-garden","riverwalk","meridian-fitness"]}'::jsonb),
  ('lark-botanical-garden','{"summary":"A glasshouse and garden path that briefly separates visitors from the pace of the city.","atmosphere":["lush","quiet","gently romantic"],"sensoryDetails":["humid glasshouse air","wet stone after misting","herbal and floral scents changing between rooms"],"signatureDetails":["central glasshouse","fern corridor","long outdoor garden path"],"layout":["entry garden","main glasshouse","smaller climate rooms","looping outdoor path"],"crowdRhythm":{"morning":"Photographers and quiet walkers arrive early.","afternoon":"The glasshouse is busiest while the outer path stays calmer.","evening":"The garden closes before most nightlife begins."},"conversationHooks":["which room feels least like the city","the plant label with the strangest story","where the light is best for a photo"],"stableFacts":["The garden closes at 6 PM.","The glasshouse and outdoor path have distinct environments."],"localEtiquette":["Stay on marked paths and do not touch protected plants."],"nearbyLocationSlugs":["halcyon-park","moss-and-crumb","riverwalk"]}'::jsonb)
)
update public.together_locations location
set canonical_lore=lore.canonical_lore,
    updated_at=now()
from lore
where location.world_id='10000000-0000-4000-8000-000000000001'
  and location.slug=lore.slug;

comment on column public.together_locations.canonical_lore is
  'Stable authored place facts for dialogue, UI, interactions, and recommendations. Dynamic scene state must not be stored here.';

commit;
